===== FILE: index.html =====
<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>素华衣舍 · 东方自然主义女装 | 二〇二六春夏系列</title>
  <style>
    :root {
      --bg-paper: #FAF7F2;
      --bg-warm: #F3EDE2;
      --bg-card: #FFFFFF;
      --text-ink: #242321;
      --text-muted: #6E6A63;
      --text-light: #9A948C;
      --accent-jade: #3B5B4F;
      --accent-jade-dark: #2A433A;
      --accent-lotus: #9E6B62;
      --accent-gold: #B89660;
      --border-subtle: #E5DEC9;
      --shadow-soft: 0 10px 30px rgba(36, 35, 33, 0.06);
      --radius-sm: 4px;
      --radius-md: 8px;
      --font-serif: "Songti SC", "STSong", "Noto Serif SC", "Source Han Serif SC", "SimSun", serif;
      --font-sans: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      background-color: var(--bg-paper);
      color: var(--text-ink);
      font-family: var(--font-sans);
      line-height: 1.7;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; transition: color 0.25s ease; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    .serif { font-family: var(--font-serif); }

    /* 顶部通告栏 */
    .top-bar {
      background-color: var(--accent-jade);
      color: #F4EFE6;
      font-size: 13px;
      letter-spacing: 0.08em;
      text-align: center;
      padding: 9px 16px;
      display: flex;
      justify-content: center;
      align-items: center;
      gap: 24px;
      flex-wrap: wrap;
    }

    /* 导航栏 */
    .site-header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(250, 247, 242, 0.95);
      backdrop-filter: blur(8px);
      border-bottom: 1px solid var(--border-subtle);
    }
    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 28px;
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .brand-logo {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .brand-logo-mark {
      width: 38px;
      height: 38px;
      border: 1.5px solid var(--accent-jade);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-serif);
      font-size: 18px;
      color: var(--accent-jade);
      background: var(--bg-warm);
    }
    .brand-title {
      font-family: var(--font-serif);
      font-size: 24px;
      letter-spacing: 0.18em;
      font-weight: 600;
    }
    .brand-sub {
      font-size: 11px;
      color: var(--text-muted);
      letter-spacing: 0.15em;
      display: block;
      margin-top: -4px;
    }
    .main-nav {
      display: flex;
      align-items: center;
      gap: 36px;
    }
    .nav-link {
      font-size: 15px;
      letter-spacing: 0.1em;
      padding: 6px 0;
      position: relative;
    }
    .nav-link::after {
      content: "";
      position: absolute;
      left: 0;
      bottom: 0;
      width: 0;
      height: 1.5px;
      background-color: var(--accent-jade);
      transition: width 0.25s ease;
    }
    .nav-link:hover::after,
    .nav-link.active::after {
      width: 100%;
    }
    .nav-link.active {
      color: var(--accent-jade);
      font-weight: 500;
    }
    .header-actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }
    .action-btn {
      font-size: 14px;
      color: var(--text-ink);
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 7px 14px;
      border-radius: 999px;
      border: 1px solid var(--border-subtle);
      background: var(--bg-card);
      transition: all 0.2s ease;
    }
    .action-btn:hover {
      border-color: var(--accent-jade);
      color: var(--accent-jade);
    }
    .badge-count {
      background: var(--accent-jade);
      color: #fff;
      font-size: 11px;
      padding: 1px 7px;
      border-radius: 99px;
    }

    /* 主视觉海报 */
    .hero-section {
      max-width: 1280px;
      margin: 28px auto 64px;
      padding: 0 28px;
    }
    .hero-card {
      background: linear-gradient(125deg, #EFE9DC 0%, #E3DDD0 55%, #D6CFC0 100%);
      border-radius: var(--radius-md);
      overflow: hidden;
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      min-height: 520px;
      border: 1px solid var(--border-subtle);
      box-shadow: var(--shadow-soft);
    }
    .hero-text {
      padding: 64px 56px;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }
    .season-tag {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      letter-spacing: 0.2em;
      color: var(--accent-jade);
      margin-bottom: 18px;
    }
    .season-tag::before {
      content: "";
      width: 24px;
      height: 1px;
      background: var(--accent-jade);
    }
    .hero-heading {
      font-family: var(--font-serif);
      font-size: 44px;
      line-height: 1.28;
      letter-spacing: 0.08em;
      margin-bottom: 20px;
      font-weight: 500;
    }
    .hero-desc {
      font-size: 16px;
      color: var(--text-muted);
      max-width: 480px;
      margin-bottom: 36px;
      line-height: 1.85;
    }
    .hero-cta-group {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }
    .btn-primary {
      background: var(--accent-jade);
      color: #fff;
      padding: 13px 30px;
      font-size: 15px;
      letter-spacing: 0.12em;
      border-radius: var(--radius-sm);
      transition: background 0.25s ease;
      display: inline-block;
      text-align: center;
    }
    .btn-primary:hover {
      background: var(--accent-jade-dark);
    }
    .btn-outline {
      border: 1px solid var(--text-ink);
      color: var(--text-ink);
      padding: 13px 28px;
      font-size: 15px;
      letter-spacing: 0.12em;
      border-radius: var(--radius-sm);
      transition: all 0.25s ease;
      display: inline-block;
      text-align: center;
    }
    .btn-outline:hover {
      background: var(--text-ink);
      color: #fff;
    }
    .hero-visual {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 32px;
      background: radial-gradient(circle at 60% 45%, rgba(255,255,255,0.6), transparent 70%);
    }

    /* 品牌亮点 */
    .pillars-section {
      max-width: 1280px;
      margin: 0 auto 72px;
      padding: 0 28px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .pillar-card {
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      padding: 28px 30px;
      border-radius: var(--radius-sm);
      display: flex;
      gap: 18px;
      align-items: flex-start;
    }
    .pillar-icon {
      width: 46px;
      height: 46px;
      border-radius: 50%;
      background: var(--bg-warm);
      color: var(--accent-jade);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-family: var(--font-serif);
      font-size: 19px;
      border: 1px solid var(--border-subtle);
    }
    .pillar-title {
      font-family: var(--font-serif);
      font-size: 18px;
      margin-bottom: 6px;
      letter-spacing: 0.06em;
    }
    .pillar-text {
      font-size: 13.5px;
      color: var(--text-muted);
    }

    /* 章节标题 */
    .section-header {
      max-width: 1280px;
      margin: 0 auto 36px;
      padding: 0 28px;
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      flex-wrap: wrap;
      gap: 16px;
    }
    .section-eyebrow {
      font-size: 12px;
      letter-spacing: 0.2em;
      color: var(--accent-jade);
      margin-bottom: 6px;
      display: block;
    }
    .section-title {
      font-family: var(--font-serif);
      font-size: 30px;
      font-weight: 500;
      letter-spacing: 0.08em;
    }
    .section-more {
      font-size: 14px;
      color: var(--accent-jade);
      letter-spacing: 0.08em;
      border-bottom: 1px solid var(--accent-jade);
      padding-bottom: 2px;
    }

    /* 商品展示网格 */
    .featured-grid {
      max-width: 1280px;
      margin: 0 auto 80px;
      padding: 0 28px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 26px;
    }
    .product-card {
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-sm);
      overflow: hidden;
      transition: transform 0.25s ease, box-shadow 0.25s ease;
      display: flex;
      flex-direction: column;
    }
    .product-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-soft);
    }
    .product-thumb {
      position: relative;
      height: 310px;
      background: var(--bg-warm);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
      cursor: pointer;
    }
    .product-badge {
      position: absolute;
      top: 12px;
      left: 12px;
      background: rgba(59, 91, 79, 0.9);
      color: #fff;
      font-size: 11px;
      padding: 3px 10px;
      letter-spacing: 0.08em;
      border-radius: 2px;
    }
    .product-info {
      padding: 18px 20px 22px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }
    .product-fabric-tag {
      font-size: 12px;
      color: var(--accent-lotus);
      margin-bottom: 4px;
      letter-spacing: 0.05em;
    }
    .product-name {
      font-family: var(--font-serif);
      font-size: 17px;
      margin-bottom: 8px;
      letter-spacing: 0.04em;
      cursor: pointer;
    }
    .product-meta {
      margin-top: auto;
      padding-top: 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-top: 1px dashed var(--border-subtle);
    }
    .product-price {
      font-size: 17px;
      font-weight: 600;
      color: var(--text-ink);
    }
    .add-bag-btn {
      font-size: 13px;
      color: var(--accent-jade);
      border: 1px solid var(--accent-jade);
      padding: 5px 12px;
      border-radius: 2px;
      transition: all 0.2s ease;
    }
    .add-bag-btn:hover {
      background: var(--accent-jade);
      color: #fff;
    }

    /* 四大天然织物实验室 */
    .fabric-showcase {
      background: var(--bg-warm);
      padding: 76px 28px;
      margin-bottom: 80px;
      border-top: 1px solid var(--border-subtle);
      border-bottom: 1px solid var(--border-subtle);
    }
    .fabric-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 0.95fr 1.05fr;
      gap: 48px;
      align-items: center;
    }
    .fabric-tabs {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 14px;
      margin-top: 24px;
    }
    .fabric-tab {
      text-align: left;
      padding: 18px 20px;
      background: var(--bg-paper);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-sm);
      transition: all 0.2s ease;
    }
    .fabric-tab.active {
      border-color: var(--accent-jade);
      background: var(--bg-card);
      box-shadow: var(--shadow-soft);
    }
    .fabric-tab h4 {
      font-family: var(--font-serif);
      font-size: 17px;
      margin-bottom: 4px;
      color: var(--text-ink);
    }
    .fabric-tab p {
      font-size: 12.5px;
      color: var(--text-muted);
    }
    .fabric-detail-panel {
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-md);
      padding: 40px;
      box-shadow: var(--shadow-soft);
    }
    .fabric-specs {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-top: 24px;
      padding-top: 20px;
      border-top: 1px solid var(--border-subtle);
    }
    .spec-box span {
      display: block;
      font-size: 12px;
      color: var(--text-muted);
    }
    .spec-box strong {
      font-family: var(--font-serif);
      font-size: 17px;
      color: var(--accent-jade);
    }

    /* 顾客口碑 */
    .reviews-section {
      max-width: 1280px;
      margin: 0 auto 88px;
      padding: 0 28px;
    }
    .reviews-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .review-card {
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      padding: 28px;
      border-radius: var(--radius-sm);
    }
    .review-quote {
      font-size: 14.5px;
      color: var(--text-ink);
      margin-bottom: 18px;
      line-height: 1.8;
    }
    .review-author {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 12.5px;
      color: var(--text-muted);
      border-top: 1px solid var(--border-subtle);
      padding-top: 12px;
    }

    /* 页脚 */
    .site-footer {
      background: #22211F;
      color: #D8D2C7;
      padding: 64px 28px 36px;
    }
    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
      gap: 40px;
      padding-bottom: 44px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
    .footer-brand h3 {
      font-family: var(--font-serif);
      font-size: 22px;
      color: #fff;
      letter-spacing: 0.15em;
      margin-bottom: 12px;
    }
    .footer-brand p {
      font-size: 13.5px;
      color: #9E988E;
      max-width: 320px;
      margin-bottom: 18px;
    }
    .footer-col h4 {
      font-family: var(--font-serif);
      font-size: 16px;
      color: #fff;
      margin-bottom: 16px;
      letter-spacing: 0.08em;
    }
    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
      font-size: 13.5px;
      color: #A9A399;
    }
    .footer-links a:hover { color: #fff; }
    .footer-bottom {
      max-width: 1280px;
      margin: 28px auto 0;
      display: flex;
      justify-content: space-between;
      font-size: 12.5px;
      color: #7E7970;
      flex-wrap: wrap;
      gap: 12px;
    }

    /* 购物袋抽屉与详情弹窗 */
    .drawer-backdrop, .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(25, 24, 22, 0.45);
      z-index: 200;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.25s ease;
    }
    .drawer-backdrop.open, .modal-overlay.open {
      opacity: 1;
      pointer-events: auto;
    }
    .bag-drawer {
      position: fixed;
      top: 0;
      right: 0;
      width: 400px;
      max-width: 92vw;
      height: 100vh;
      background: var(--bg-paper);
      z-index: 210;
      transform: translateX(100%);
      transition: transform 0.3s ease;
      display: flex;
      flex-direction: column;
      box-shadow: -8px 0 30px rgba(0,0,0,0.12);
    }
    .bag-drawer.open { transform: translateX(0); }
    .drawer-header {
      padding: 20px 24px;
      border-bottom: 1px solid var(--border-subtle);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .drawer-header h3 { font-family: var(--font-serif); font-size: 19px; }
    .close-btn {
      font-size: 14px;
      color: var(--text-muted);
      padding: 4px 10px;
      border: 1px solid var(--border-subtle);
      border-radius: 2px;
    }
    .drawer-body {
      flex: 1;
      overflow-y: auto;
      padding: 20px 24px;
    }
    .bag-item {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 14px 0;
      border-bottom: 1px solid var(--border-subtle);
      gap: 12px;
    }
    .bag-item-title { font-family: var(--font-serif); font-size: 15px; }
    .bag-item-sub { font-size: 12px; color: var(--text-muted); }
    .qty-controls {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 6px;
    }
    .qty-btn {
      width: 24px;
      height: 24px;
      border: 1px solid var(--border-subtle);
      background: var(--bg-card);
      font-size: 13px;
    }
    .drawer-footer {
      padding: 20px 24px;
      border-top: 1px solid var(--border-subtle);
      background: var(--bg-warm);
    }
    .bag-total-row {
      display: flex;
      justify-content: space-between;
      font-size: 16px;
      font-weight: 600;
      margin-bottom: 14px;
    }
    .checkout-btn {
      width: 100%;
      background: var(--accent-jade);
      color: #fff;
      padding: 13px;
      font-size: 15px;
      letter-spacing: 0.1em;
      border-radius: var(--radius-sm);
    }

    /* 详情弹窗 */
    .modal-overlay {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
    }
    .modal-card {
      background: var(--bg-paper);
      max-width: 780px;
      width: 100%;
      border-radius: var(--radius-md);
      border: 1px solid var(--border-subtle);
      overflow: hidden;
      display: grid;
      grid-template-columns: 1fr 1.1fr;
      box-shadow: 0 20px 50px rgba(0,0,0,0.18);
    }
    .modal-visual {
      background: var(--bg-warm);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 32px;
    }
    .modal-content {
      padding: 32px;
      display: flex;
      flex-direction: column;
    }
    .option-group { margin: 14px 0; }
    .option-label { font-size: 12.5px; color: var(--text-muted); margin-bottom: 6px; display: block; }
    .option-pills { display: flex; gap: 8px; flex-wrap: wrap; }
    .option-pill {
      padding: 5px 14px;
      font-size: 13px;
      border: 1px solid var(--border-subtle);
      background: var(--bg-card);
      border-radius: 2px;
    }
    .option-pill.selected {
      border-color: var(--accent-jade);
      background: var(--accent-jade);
      color: #fff;
    }

    .toast-msg {
      position: fixed;
      bottom: 28px;
      left: 50%;
      transform: translateX(-50%) translateY(20px);
      background: var(--accent-jade);
      color: #fff;
      padding: 10px 24px;
      border-radius: 99px;
      font-size: 14px;
      opacity: 0;
      pointer-events: none;
      transition: all 0.25s ease;
      z-index: 300;
    }
    .toast-msg.show {
      opacity: 1;
      transform: translateX(-50%) translateY(0);
    }

    @media (max-width: 960px) {
      .hero-card, .fabric-inner, .modal-card { grid-template-columns: 1fr; }
      .featured-grid { grid-template-columns: repeat(2, 1fr); }
      .pillars-section, .reviews-grid, .footer-inner { grid-template-columns: 1fr; }
      .header-inner { flex-wrap: wrap; height: auto; padding: 14px 20px; gap: 12px; }
      .main-nav { gap: 20px; width: 100%; justify-content: center; border-top: 1px solid var(--border-subtle); padding-top: 10px; }
    }
    @media (max-width: 560px) {
      .featured-grid { grid-template-columns: 1fr; }
      .hero-heading { font-size: 32px; }
      .hero-text { padding: 36px 24px; }
    }
  </style>
</head>
<body>

  <!-- 顶部通告栏 -->
  <div class="top-bar">
    <span>二〇二六春夏「林间初霁」系列现已上市</span>
    <span>|</span>
    <span>全场顺丰包邮 · 附赠天然雪松木防虫衣香片</span>
  </div>

  <!-- 网站头部导航 -->
  <header class="site-header">
    <div class="header-inner">
      <a href="index.html" class="brand-logo">
        <div class="brand-logo-mark">素</div>
        <div>
          <span class="brand-title">素华衣舍</span>
          <span class="brand-sub">东方自然主义女装</span>
        </div>
      </a>

      <nav class="main-nav" aria-label="主导航">
        <a href="index.html" class="nav-link active">首页</a>
        <a href="collection.html" class="nav-link">全部衣裳</a>
        <a href="lookbook.html" class="nav-link">穿搭画册</a>
        <a href="about.html" class="nav-link">品牌与门店</a>
      </nav>

      <div class="header-actions">
        <a href="collection.html#sizeAdvisorSection" class="action-btn">量体选码</a>
        <button class="action-btn" id="openBagBtn" aria-label="查看购物袋">
          <span>购物袋</span>
          <span class="badge-count" id="bagCountBadge">0</span>
        </button>
      </div>
    </div>
  </header>

  <!-- 主视觉海报 -->
  <section class="hero-section">
    <div class="hero-card">
      <div class="hero-text">
