    let currentCat = "全部";
    let searchTerm = "";
    let sortMode = "default";

    function renderCatalog() {
      const grid = document.getElementById("catalogGrid");
      let list = ALL_PRODUCTS.filter(p => {
        const matchCat = currentCat === "全部" || p.category === currentCat;
        const matchSearch = !searchTerm || p.name.includes(searchTerm) || p.fabric.includes(searchTerm);
        return matchCat && matchSearch;
      });

      if (sortMode === "asc") list.sort((a, b) => a.price - b.price);
      if (sortMode === "desc") list.sort((a, b) => b.price - a.price);

      grid.innerHTML = "";
      if (list.length === 0) {
        grid.innerHTML = `<p style="grid-column:1/-1; text-align:center; padding:48px; color:var(--text-muted);">未找到符合条件的衣裳，请尝试其他关键词或分类。</p>`;
        return;
      }

      list.forEach(prod => {
        const dotsHtml = prod.colors.map(c => `<span class="color-dot" title="${c.name}" style="background:${c.hex}"></span>`).join("");
        const card = document.createElement("article");
        card.className = "product-card";
        card.innerHTML = `
          <div class="product-thumb" data-quick="${prod.id}">
            <span class="product-badge">${prod.badge}</span>
            ${renderGarmentSVG(prod.svgType)}
          </div>
          <div class="product-info">
            <span class="product-fabric-tag">${prod.fabric}</span>
            <h3 class="product-name" data-quick="${prod.id}">${prod.name}</h3>
            <div class="color-dots">${dotsHtml}<span style="font-size:11.5px; color:var(--text-muted); margin-left:4px;">${prod.colors.length}色可选</span></div>
            <div class="product-meta">
              <span class="product-price">￥${prod.price}</span>
              <button class="add-bag-btn" data-quick="${prod.id}">选码添置</button>
            </div>
          </div>
        `;
        grid.appendChild(card);
      });
    }

    document.querySelectorAll(".cat-pill").forEach(btn => {
      btn.addEventListener("click", () => {
        document.querySelectorAll(".cat-pill").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        currentCat = btn.dataset.cat;
        renderCatalog();
      });
    });

    document.getElementById("searchInput").addEventListener("input", e => {
      searchTerm = e.target.value.trim();
      renderCatalog();
    });

    document.getElementById("sortSelect").addEventListener("change", e => {
      sortMode = e.target.value;
      renderCatalog();
    });

    // 量体选码助手逻辑
    document.getElementById("calcSizeBtn").addEventListener("click", () => {
      const h = Number(document.getElementById("heightInput").value) || 164;
      const w = Number(document.getElementById("weightInput").value) || 106;
      const fit = document.getElementById("fitSelect").value;

      let score = 2;
      if (w < 98 || (h < 159 && w <= 102)) score = 1;
      else if (w > 116 || h > 169) score = 3;

      if (fit === "slim" && score > 1) score -= 1;
      if (fit === "loose" && score < 3) score += 1;

      const sizeMap = {
        1: "一码（小码）",
        2: "二码（中码）",
        3: "三码（大码）"
      };
      const rec = sizeMap[score];
      document.getElementById("recSizeOutput").textContent = rec;
      document.getElementById("recSizeReason").textContent =
        `依据身高${h}厘米、体重${w}斤及您的穿着偏好测算，推荐选择「${rec}」，肩袖与胸围处保有舒适东方余量。`;
    });

    // 购物袋逻辑
    const BAG_KEY = "suhua_shopping_bag_v1";
    function getBag() {
      try { return JSON.parse(localStorage.getItem(BAG_KEY)) || []; } catch (e) { return []; }
    }
    function saveBag(bag) {
      localStorage.setItem(BAG_KEY, JSON.stringify(bag));
      renderBagUI();
    }
    function addToBag(item) {
      const bag = getBag();
      const ex = bag.find(i => i.id === item.id && i.color === item.color && i.size === item.size);
      if (ex) ex.qty += 1; else bag.push({ ...item, qty: 1 });
      saveBag(bag);
      showToast(`已将「${item.name}」加入购物袋`);
    }
    function renderBagUI() {
      const bag = getBag();
      document.getElementById("bagCountBadge").textContent = bag.reduce((s, i) => s + i.qty, 0);
      const container = document.getElementById("bagItemsContainer");
      const totalEl = document.getElementById("bagTotalAmount");
      if (bag.length === 0) {
        container.innerHTML = `<p style="text-align:center; color:var(--text-muted); padding: 48px 0;">购物袋尚无衣裳，欢迎挑选心仪之作。</p>`;
        totalEl.textContent = "￥0";
        return;
      }
      let total = 0;
      container.innerHTML = "";
      bag.forEach((item, idx) => {
        total += item.price * item.qty;
        const row = document.createElement("div");
        row.className = "bag-item";
        row.innerHTML = `
          <div>
            <div style="font-family:var(--font-serif); font-size:15px;">${item.name}</div>
            <div style="font-size:12px; color:var(--text-muted);">色泽：${item.color} ｜ 尺码：${item.size}</div>
            <div class="qty-controls">
              <button class="qty-btn" data-idx="${idx}" data-delta="-1">－</button>
              <span style="font-size:13px;">${item.qty}</span>
              <button class="qty-btn" data-idx="${idx}" data-delta="1">＋</button>
            </div>
          </div>
          <div style="font-weight:600;">￥${item.price * item.qty}</div>
        `;
        container.appendChild(row);
      });
      totalEl.textContent = "￥" + total;
      container.querySelectorAll(".qty-btn").forEach(btn => {
        btn.addEventListener("click", () => {
          const idx = Number(btn.dataset.idx);
          const delta = Number(btn.dataset.delta);
          const cur = getBag();
          cur[idx].qty += delta;
          if (cur[idx].qty <= 0) cur.splice(idx, 1);
          saveBag(cur);
        });
      });
    }

    // 弹窗逻辑
    let activeProduct = null;
    let selectedColor = "";
    let selectedSize = "二码（中码）";

    function openQuickModal(prodId) {
      const prod = ALL_PRODUCTS.find(p => p.id === prodId);
      if (!prod) return;
      activeProduct = prod;
      selectedColor = prod.colors[0].name;
      selectedSize = "二码（中码）";

      document.getElementById("modalSvgHolder").innerHTML = renderGarmentSVG(prod.svgType);
      document.getElementById("modalFabric").textContent = prod.fabric;
      document.getElementById("modalTitle").textContent = prod.name;
      document.getElementById("modalPrice").textContent = "￥" + prod.price;
      document.getElementById("modalDesc").textContent = prod.desc;
      document.getElementById("modalCare").textContent = prod.care;

      const colorHolder = document.getElementById("modalColorPills");
      colorHolder.innerHTML = "";
      prod.colors.forEach((c, i) => {
        const b = document.createElement("button");
        b.className = "option-pill" + (i === 0 ? " selected" : "");
        b.textContent = c.name;
        b.addEventListener("click", () => {
          colorHolder.querySelectorAll(".option-pill").forEach(p => p.classList.remove("selected"));
          b.classList.add("selected");
          selectedColor = c.name;
        });
        colorHolder.appendChild(b);
      });

      document.getElementById("quickViewModal").classList.add("open");
    }

    document.getElementById("modalSizePills").querySelectorAll(".option-pill").forEach(btn => {
      btn.addEventListener("click", () => {
        document.getElementById("modalSizePills").querySelectorAll(".option-pill").forEach(p => p.classList.remove("selected"));
        btn.classList.add("selected");
        selectedSize = btn.dataset.size;
      });
    });

    document.getElementById("modalAddBagBtn").addEventListener("click", () => {
      if (!activeProduct) return;
      addToBag({
        id: activeProduct.id,
        name: activeProduct.name,
        price: activeProduct.price,
        color: selectedColor,
        size: selectedSize
      });
      document.getElementById("quickViewModal").classList.remove("open");
    });

    document.addEventListener("click", e => {
      const trigger = e.target.closest("[data-quick]");
      if (trigger) openQuickModal(trigger.dataset.quick);
    });

    document.getElementById("closeModalBtn").addEventListener("click", () => {
      document.getElementById("quickViewModal").classList.remove("open");
    });

    const bagDrawer = document.getElementById("bagDrawer");
    const backdrop = document.getElementById("drawerBackdrop");
    document.getElementById("openBagBtn").addEventListener("click", () => {
      bagDrawer.classList.add("open");
      backdrop.classList.add("open");
    });
    function closeBag() {
      bagDrawer.classList.remove("open");
      backdrop.classList.remove("open");
    }
    document.getElementById("closeBagBtn").addEventListener("click", closeBag);
    backdrop.addEventListener("click", closeBag);

    document.getElementById("checkoutBtn").addEventListener("click", () => {
      const bag = getBag();
      if (bag.length === 0) { showToast("您的购物袋尚无衣裳"); return; }
      localStorage.removeItem(BAG_KEY);
      renderBagUI();
      closeBag();
      showToast("订单已生成，顺丰专递将为您寄出衣裳与雪松木香片");
    });

    function showToast(msg) {
      const t = document.getElementById("toastMsg");
      t.textContent = msg;
      t.classList.add("show");
      setTimeout(() => t.classList.remove("show"), 2600);
    }

    renderCatalog();
    renderBagUI();
  </script>
</body>
</html>
